export { contentView, panelView, rootView, triggerView } from "../collapsible";
export type {
  CollapsibleStyle,
  PanelViewConfig,
  RootViewConfig,
  TriggerViewConfig,
} from "../collapsible";

export {
  shadcnCollapsibleContentClassName,
  shadcnCollapsibleIconClassName,
  shadcnCollapsiblePanelClassName,
  shadcnCollapsibleRootClassName,
  shadcnCollapsibleTriggerClassName,
} from "./view";

export {
  collapsibleContentClassName as shadcnCollapsibleContentClassName,
  collapsibleIconClassName as shadcnCollapsibleIconClassName,
  collapsiblePanelClassName as shadcnCollapsiblePanelClassName,
  collapsibleRootClassName as shadcnCollapsibleRootClassName,
  collapsibleTriggerClassName as shadcnCollapsibleTriggerClassName,
} from "../collapsible/view";

import { describe, expect, test } from "vitest";

import * as Collapsible from "./index";

describe("shadcn Collapsible registry view", () => {
  test("reuses the Foldkit Collapsible view contract", () => {
    expect(Collapsible.rootView).toBeTypeOf("function");
    expect(Collapsible.triggerView).toBeTypeOf("function");
    expect(Collapsible.panelView).toBeTypeOf("function");
    expect(Collapsible.shadcnCollapsibleTriggerClassName).toContain(
      "font-medium"
    );
  });
});
